const assertEnabled=()=>{if(process.env.NODE_ENV==="production"||process.env.DISCOVERY_STUDIO_ENABLED!=="1")throw new Error("Discovery Studio is disabled.")};
const normalize=(parsed:any):StudioScenarioV1=>{if(parsed?.contractVersion==="3"){const{scenarioDigest:_scenario,sourcePacketDigest:_packet,...input}=parsed;return createStudioScenarioV3(input)}const value={...parsed,events:parsed.events.map((event:any)=>{const{eventDigest:_stale,...base}=event;return{...base,eventDigest:productArtifactBodyDigest(base)}})};assertStudioScenarioIntegrity(value);return value};
