function variant(base:StudioScenarioV1,scenarioId:string,scenarioVersion:string,enabled:Set<string>):StudioScenarioV1{return normalize({...base,scenarioId,scenarioVersion,name:`${base.name} — ${scenarioVersion}`,events:base.events.map(event=>({...event,enabled:enabled.has(event.eventId)}))})}
async function controlledScenarios(){const fixture=normalize(JSON.parse(await readFile("fixtures/discovery-studio/northstar-delivery-recovery-v1.json","utf8"))),m1=new Set(["m1-leadership-capture","m1-audit-rework-evidence"]),m2=new Set([...m1,"m2-sso-resolution","m2-tie-break-readiness","m2-vendor-sandbox","m2-executive-attention"]),contradiction=new Set([...m2,"m2-staffing-contradiction"]);return[
 variant(fixture,"northstar-controlled-m1","m1",m1),
 variant(fixture,"northstar-controlled-m1-repeat","m1-repeat",m1),
 variant(fixture,"northstar-controlled-m1-without-audit","m1-without-audit",new Set(["m1-leadership-capture"])),
 variant(fixture,"northstar-controlled-m2","m2-temporal",m2),
 variant(fixture,"northstar-controlled-m2-contradiction","m2-contradiction",contradiction)
]}

export async function loadNorthstarAction(){assertEnabled();const value=normalize(JSON.parse(await readFile("fixtures/discovery-studio/northstar-delivery-recovery-v1.json","utf8")));await saveScenario(value);revalidatePath("/dev/discovery-studio");return value}
export async function saveScenarioAction(json:string){assertEnabled();const value=normalize(JSON.parse(json));if(value.contractVersion==="3")await replaceScenario(value);else await saveScenario(value);revalidatePath("/dev/discovery-studio");return value}
