export async function importGenericScenarioAction(json:string){assertEnabled();const value=normalize(JSON.parse(json));if(value.contractVersion!=="3")throw new Error("Generic scenario import requires contract version 3.");await saveScenario(value);return value}
export async function duplicateGenericScenarioAction(scenarioId:string,input:{scenarioId:string;scenarioVersion:string;variantKind:StudioScenarioV3["variantKind"];predecessorScenarioId:string|null}){assertEnabled();const source=await loadScenario(scenarioId);if(source.contractVersion!=="3")throw new Error("Only a generic scenario can be duplicated.");const{scenarioDigest:_scenario,sourcePacketDigest:_packet,...base}=source,value=createStudioScenarioV3({...base,...input,name:`${source.scenarioFamilyTitle} — ${input.scenarioVersion}`});await saveScenario(value);return value}
export async function deleteGenericScenarioAction(scenarioId:string){assertEnabled();const scenario=await loadScenario(scenarioId);if(scenario.contractVersion!=="3")throw new Error("Only a generic scenario can be deleted through this action.");await deleteScenario(scenarioId)}
export async function createGenericRunPlanAction(input:{scenarioId:string;runName:string}){assertEnabled();const scenario=await loadScenario(input.scenarioId);if(scenario.contractVersion!=="3")throw new Error("Generic run plans require scenario contract version 3.");const source=await computeStudioSourceIdentity(),base={contractVersion:"1" as const,planId:`studio-plan-${randomUUID()}`,scenarioId:scenario.scenarioId,scenarioFamilyId:scenario.scenarioFamilyId,variantKind:scenario.variantKind,scenarioDigest:scenario.scenarioDigest,sourcePacketDigest:scenario.sourcePacketDigest,runName:input.runName,mode:"fresh-understanding" as const,capabilities:STUDIO_CAPABILITIES,accessRoleIdentity:"development-local-synthetic" as const,frozenAnalysisIdentity:FROZEN_DISCOVERY_ANALYSIS_IDENTITY,evaluationToolingIdentity:source.sourceManifestDigest},plan={...base,planDigest:studioDigest(base)};return saveGenericRunPlan(plan)}
export async function executeGenericRunPlanAction(planId:string){assertEnabled();const plan=await loadGenericRunPlan(planId),scenario=await loadScenario(plan.scenarioId);if(scenario.contractVersion!=="3"||scenario.scenarioFamilyId!==plan.scenarioFamilyId||scenario.variantKind!==plan.variantKind||scenario.scenarioDigest!==plan.scenarioDigest||scenario.sourcePacketDigest!==plan.sourcePacketDigest)throw new Error("Generic run plan scenario binding is invalid.");const source=await computeStudioSourceIdentity();if(source.sourceManifestDigest!==plan.evaluationToolingIdentity||plan.frozenAnalysisIdentity!==FROZEN_DISCOVERY_ANALYSIS_IDENTITY)throw new Error("Generic run plan tooling binding is stale.");const run=await runStudioScenario(scenario,{runName:plan.runName,experimentId:scenario.scenarioFamilyId,experimentName:scenario.scenarioFamilyTitle,mode:"fresh-understanding",comparisonKind:scenario.predecessorScenarioId?"temporal-update":"generic-repeat",sourceIdentity:source});await saveRun(run);const receiptBase={contractVersion:"1" as const,planId:plan.planId,planDigest:plan.planDigest,runId:run.runId,runDigest:run.runDigest,scenarioId:scenario.scenarioId,scenarioFamilyId:scenario.scenarioFamilyId,variantKind:scenario.variantKind,scenarioDigest:scenario.scenarioDigest,sourcePacketDigest:scenario.sourcePacketDigest,frozenAnalysisIdentity:plan.frozenAnalysisIdentity,evaluationToolingIdentity:plan.evaluationToolingIdentity},receipt={...receiptBase,receiptDigest:studioDigest(receiptBase)};await saveGenericRunReceipt(receipt);return run}
export async function exportFutureFrontierSourceOnlyAction(scenarioId:string){assertEnabled();const scenario=await loadScenario(scenarioId);if(scenario.contractVersion!=="3")throw new Error("Future frontier packet requires scenario contract version 3.");return saveFutureFrontierSourceOnlyPacket(buildFutureFrontierSourceOnlyPacket(scenario))}
export async function runNamedScenarioAction(input:{scenarioId:string;runName:string;experimentId:string;experimentName:string;mode:StudioRunMode;comparisonKind:StudioComparisonKind}){assertEnabled();const run=await runStudioScenario(await loadScenario(input.scenarioId),input);await saveRun(run);revalidatePath("/dev/discovery-studio");return run}
export async function runScenarioAction(id:string,runName="generic-candidate",experimentId="manual-studio-experiment",experimentName="Manual Studio experiment"){return runNamedScenarioAction({scenarioId:id,runName,experimentId,experimentName,mode:"fresh-understanding",comparisonKind:"generic-repeat"})}
export async function runBaselineAction(id:string,runName="canonical-baseline",experimentId="manual-studio-experiment",experimentName="Manual Studio experiment"){return runNamedScenarioAction({scenarioId:id,runName,experimentId,experimentName,mode:"fixture-baseline",comparisonKind:"canonical-versus-generic"})}
export async function saveScorecardAction(runId:string,input:Omit<StudioScorecardV1,"contractVersion"|"runId"|"scenarioDigest"|"sourceCommit"|"understandingConfiguration"|"presentationConfiguration"|"scorecardDigest">){assertEnabled();const run=await loadRun(runId),prior=await loadScorecard(run),scorecard=createStudioScorecard(run,{...input,updatedCategory:prior?"updated":"created"});return saveScorecard(scorecard,run)}
export async function compareRunsAction(input:{earlierRunId:string;laterRunId:string;comparisonName:string;kind:StudioComparisonKind}){
 assertEnabled();const earlier=await loadRun(input.earlierRunId),loadedLater=await loadRun(input.laterRunId);let later=loadedLater;
 if(input.kind==="presentation-only"){
  if(earlier.runId!==loadedLater.runId)throw new Error("Presentation-only comparison requires one frozen source run.");
  later=createPresentationOnlyVariant(earlier,await loadScenario(earlier.scenarioId));await saveRun(later);
 }
 const scenarioEarlier=await loadScenario(earlier.scenarioId),scenarioLater=await loadScenario(later.scenarioId);if(scenarioEarlier.contractVersion==="3"||scenarioLater.contractVersion==="3"){if(scenarioEarlier.contractVersion!=="3"||scenarioLater.contractVersion!=="3"||scenarioEarlier.scenarioFamilyId!==scenarioLater.scenarioFamilyId||scenarioLater.predecessorScenarioId!==scenarioEarlier.scenarioId||input.kind!=="temporal-update")throw new Error("Generic comparisons require an exact same-family predecessor temporal pair.")}const comparison=compareRuns({comparisonName:input.comparisonName,kind:input.kind,earlier,later,scenarioEarlier,scenarioLater,earlierScorecard:await loadScorecard(earlier),laterScorecard:await loadScorecard(later)});await saveComparison(comparison);revalidatePath("/dev/discovery-studio");return comparison;
}
export async function exportComparisonAction(comparisonId:string){assertEnabled();const comparison=await loadComparison(comparisonId),earlier=await loadRun(comparison.earlierRunId),later=await loadRun(comparison.laterRunId);return exportReviewPacket({earlierScenario:await loadScenario(earlier.scenarioId),laterScenario:await loadScenario(later.scenarioId),earlierRun:earlier,laterRun:later,comparison,earlierScorecard:await loadScorecard(earlier),laterScorecard:await loadScorecard(later)})}

export async function prepareControlledNorthstarEvaluationSetAction(){assertEnabled();const sourceIdentity=await computeStudioSourceIdentity(),scenarios=await controlledScenarios();for(const scenario of scenarios)await saveScenario(scenario);const byId=new Map(scenarios.map(x=>[x.scenarioId,x])),base={contractVersion:"1" as const,experimentId:EXPERIMENT_ID,experimentName:EXPERIMENT_NAME,sourceIdentity,runPlans:RUN_PLANS.map(plan=>({...plan,enabledEventIds:byId.get(plan.scenarioId)!.events.filter(x=>x.enabled).map(x=>x.eventId)})),comparisonPlans:COMPARISON_PLANS},plan={...base,planDigest:studioDigest(base)};await saveEvaluationPlan(plan);revalidatePath("/dev/discovery-studio");return plan}
export async function executeControlledNorthstarEvaluationSetAction(){assertEnabled();let plan:StudioEvaluationPlanV1;try{plan=await loadEvaluationPlan(EXPERIMENT_ID)}catch{plan=await prepareControlledNorthstarEvaluationSetAction()}const currentSource=await computeStudioSourceIdentity();if(currentSource.sourceManifestDigest!==plan.sourceIdentity.sourceManifestDigest)throw new Error("Controlled evaluation source changed after plan freeze.");const existing=(await listRuns()).filter(x=>x.experimentId===EXPERIMENT_ID);if(existing.length&&existing.length!==7)throw new Error("Partial controlled experiment exists; preserve and inspect it before retry.");const runs=existing.length===7?existing:[];if(!runs.length){for(const item of plan.runPlans){const prior=runs.find(x=>x.runName===RUN_PLANS[0].runName),run=await runStudioScenario(await loadScenario(item.scenarioId),{runName:item.runName,experimentId:EXPERIMENT_ID,experimentName:EXPERIMENT_NAME,mode:item.mode,comparisonKind:item.comparisonKind,sourceIdentity:plan.sourceIdentity,baselineRunId:item.order===2?prior?.runId??null:null});await saveRun(run);runs.push(run)}}const runByName=new Map(runs.map(x=>[x.runName,x])),comparisons=[] as ReturnType<typeof compareRuns>[];for(const item of plan.comparisonPlans){const earlier=runByName.get(item.earlierRunName)!,later=runByName.get(item.laterRunName)!,comparison=compareRuns({comparisonName:item.comparisonName,kind:item.kind,earlier,later,scenarioEarlier:await loadScenario(earlier.scenarioId),scenarioLater:await loadScenario(later.scenarioId),earlierScorecard:await loadScorecard(earlier),laterScorecard:await loadScorecard(later)});await saveComparison(comparison);await exportReviewPacket({earlierScenario:await loadScenario(earlier.scenarioId),laterScenario:await loadScenario(later.scenarioId),earlierRun:earlier,laterRun:later,comparison,earlierScorecard:await loadScorecard(earlier),laterScorecard:await loadScorecard(later)});comparisons.push(comparison)}revalidatePath("/dev/discovery-studio");return{plan,runs,comparisons}}
