type FirstFounderReviewSetup={review:BlindReviewV1;analyses:Record<string,FounderReviewAnalysisV1>;sourceStatus:"Exact source equivalence verified";runIds:[string,string,string];comparisonIds:[string,string]};
const publicReview=(review:BlindReviewV1):BlindReviewV1=>review.revealed?review:{...review,labels:review.labels.map(label=>({...label,runId:"hidden"}))};
const reviewAnalyses=(review:BlindReviewV1,artifacts:ComparableAnalysisV1[])=>Object.fromEntries(review.labels.map(label=>{const artifact=artifacts.find(item=>item.nativeRunId===label.runId);if(!artifact)throw new Error("The persisted blind review references an unavailable analysis.");return[label.label,projectFounderReviewAnalysis(artifact)]}));
async function firstFounderReviewSetup():Promise<{setup:FirstFounderReviewSetup;artifacts:[ComparableAnalysisV1,ComparableAnalysisV1,ComparableAnalysisV1];frontier:Awaited<ReturnType<typeof listFrontierRuns>>[number];canonicalComparison:ReturnType<typeof compareComparableAnalyses>;discoveryComparison:ReturnType<typeof compareComparableAnalyses>}>{const [studioRuns,frontierRuns,scenario]=await Promise.all([listRuns(),listFrontierRuns(),loadScenario("northstar-controlled-m1")]),canonical=studioRuns.find(run=>run.runId===FIRST_FOUNDER_REVIEW.canonicalRunId&&run.runName==="northstar-m1-canonical-baseline"),discovery=studioRuns.find(run=>run.runId===FIRST_FOUNDER_REVIEW.discoveryRunId&&run.runName==="northstar-m1-generic-candidate"),frontier=frontierRuns.find(run=>run.runId===FIRST_FOUNDER_REVIEW.frontierRunId&&run.runName==="northstar-m1-openai-structured-new-cohort-f212e491d893-1");if(!canonical||!discovery||!frontier||frontier.terminal!=="complete"||frontier.terminalMetadata?.structuredOutputStatus!=="valid"||frontier.terminalMetadata.semanticValidationStatus!=="PASS"||frontier.terminalMetadata.citationValidationStatus!=="PASS")throw new Error("The exact three successful analyses are unavailable.");const packet=buildFrontierSourcePacket(scenario),artifacts=[adaptStudioRun(canonical,packet),adaptStudioRun(discovery,packet),adaptFrontierRun(frontier)] as [ComparableAnalysisV1,ComparableAnalysisV1,ComparableAnalysisV1];let review:BlindReviewV1;try{review=await loadBlindReview(FIRST_FOUNDER_REVIEW.reportedBlindReviewId);assertFounderReviewSet(artifacts,review)}catch{review=createBlindReviewFromArtifacts(artifacts);assertFounderReviewSet(artifacts,review);await saveBlindReview(review)}const canonicalComparison=compareComparableAnalyses({comparisonName:"canonical-product-vs-frontier-structured-m1",artifacts:[artifacts[0],artifacts[2]]}),discoveryComparison=compareComparableAnalyses({comparisonName:"discovery-generic-vs-frontier-structured-m1",artifacts:[artifacts[1],artifacts[2]]});if(canonicalComparison.comparisonId!==FIRST_FOUNDER_REVIEW.canonicalComparisonId||discoveryComparison.comparisonId!==FIRST_FOUNDER_REVIEW.discoveryComparisonId)throw new Error("The exact Founder comparison identities are unavailable.");await saveFrontierComparison(canonicalComparison);await saveFrontierComparison(discoveryComparison);return{setup:{review:publicReview(review),analyses:reviewAnalyses(review,artifacts),sourceStatus:"Exact source equivalence verified",runIds:[canonical.runId,discovery.runId,frontier.runId],comparisonIds:[canonicalComparison.comparisonId,discoveryComparison.comparisonId]},artifacts,frontier,canonicalComparison,discoveryComparison}}
