const QUALITY_ITERATION_NAME="northstar-m1-discovery-quality-iteration-1" as const;
async function discoveryQualityIterationSetup(){const frozen=await loadBlindReview(FIRST_FOUNDER_REVIEW.reportedBlindReviewId),compact=JSON.parse(frozen.scores["Analysis C"]?.comments??"null");if(!frozen.revealed||frozen.preferredLabel!=="Analysis C"||compact?.useful!=="Analysis C"||compact?.trustworthy!=="Analysis C"||compact?.meeting!=="Analysis C")throw new Error("DISCOVERY STUDIO FOUNDER REVIEW MUST BE SAVED BEFORE OPTIMIZATION");const [scenario,sourceIdentity,frontierRuns]=await Promise.all([loadScenario("northstar-controlled-m1"),computeStudioSourceIdentity(),listFrontierRuns()]),studioRuns=await listRuns(),original=studioRuns.find(run=>run.runId===FIRST_FOUNDER_REVIEW.discoveryRunId&&run.runName==="northstar-m1-generic-candidate"),frontier=frontierRuns.find(run=>run.runId===FIRST_FOUNDER_REVIEW.frontierRunId&&run.terminal==="complete");if(!original||!frontier)throw new Error("Frozen Discovery benchmark inputs are unavailable.");let iteration=studioRuns.find(run=>run.runName===QUALITY_ITERATION_NAME);if(!iteration){iteration=await runStudioScenario(scenario,{runName:QUALITY_ITERATION_NAME,experimentId:"discovery-quality-iteration-1",experimentName:"Discovery quality iteration 1",mode:"fresh-understanding",comparisonKind:"generic-repeat",sourceIdentity,baselineRunId:original.runId});await saveRun(iteration)}else if(iteration.sourceIdentity.sourceManifestDigest!==sourceIdentity.sourceManifestDigest)throw new Error("Discovery quality iteration source identity is stale.");const packet=buildFrontierSourcePacket(scenario),artifacts=[adaptStudioRun(original,packet),adaptStudioRun(iteration,packet),adaptFrontierRun(frontier)] as [ComparableAnalysisV1,ComparableAnalysisV1,ComparableAnalysisV1],runIds=artifacts.map(artifact=>artifact.nativeRunId);let review=(await listBlindReviews()).find(candidate=>!candidate.revealed&&!Object.keys(candidate.scores).length&&candidate.labels.length===3&&candidate.labels.every(label=>runIds.includes(label.runId))&&runIds.every(id=>candidate.labels.some(label=>label.runId===id)));if(!review){review=createBlindReviewFromArtifacts(artifacts);await saveBlindReview(review)}assertDiscoveryQualityReviewSet(artifacts,review);const originalVsIteration=compareComparableAnalyses({comparisonName:"discovery-v1-vs-discovery-quality-iteration-1",artifacts:[artifacts[0],artifacts[1]]}),iterationVsFrontier=compareComparableAnalyses({comparisonName:"discovery-quality-iteration-1-vs-frozen-frontier",artifacts:[artifacts[1],artifacts[2]]});await saveFrontierComparison(originalVsIteration);await saveFrontierComparison(iterationVsFrontier);return{setup:{review:publicReview(review),analyses:reviewAnalyses(review,artifacts),sourceStatus:"Exact source equivalence verified" as const,runIds:[original.runId,iteration.runId,frontier.runId] as [string,string,string],comparisonIds:[originalVsIteration.comparisonId,iterationVsFrontier.comparisonId] as [string,string]},artifacts,frontier,comparisons:[originalVsIteration,iterationVsFrontier] as const,sourceIdentity}}
export async function openDiscoveryQualityIterationReviewAction(){assertEnabled();return(await discoveryQualityIterationSetup()).setup}
export async function exportDiscoveryQualityIterationReviewAction(){assertEnabled();const{setup,artifacts,frontier,comparisons}=await discoveryQualityIterationSetup(),review=await loadBlindReview(setup.review.blindReviewId),claim=await loadFrontierClaim(frontier.runId),founderAnalyses=review.labels.map(label=>({label:label.label,analysis:setup.analyses[label.label]!})),packet=await exportFrontierReviewPacket({comparison:comparisons[0],additionalComparisons:[comparisons[1]],runs:[frontier],blindReview:review,founderAnalyses,comparableArtifacts:artifacts,claimReceipts:[claim]});return{reviewId:review.blindReviewId,verified:true as const,packet}}
